// AUTO GENERATED subset fonts (Liberation Sans, Latin+Cyrillic+currency) for OG images.
// Subset keeps the bundle small; CJK and Devanagari are not covered (image falls back to Latin label for those).
export const OG_FONT_REGULAR_B64 = "";
export const OG_FONT_BOLD_B64 = "";

export function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
